package com.compassonly;

import java.awt.Rectangle;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Where the enlarged compass goes on the current frame, in canvas pixels.
 */
@Value
class CompassGeometry
{
	/** The space the hidden minimap occupied. */
	Rectangle minimapBounds;
	/** Sprite whose shape is the minimap's visible area, or -1. */
	int minimapMaskSprite;
	/** The space the game's own small compass occupied. */
	@Nullable
	Rectangle compassBounds;
	/** Sprite whose shape is the small compass's visible area, or -1. */
	int compassMaskSprite;

	double centerX;
	double centerY;
	/** Diameter of the enlarged compass. */
	double diameter;
	/** Diameter of the part of the compass sprite the game normally shows. */
	double sourceDiameter;
	/** Bigger than the minimap's space, so it is drawn over the interface instead of in the minimap's place. */
	boolean oversized;

	boolean contains(int x, int y)
	{
		final double dx = x - centerX;
		final double dy = y - centerY;
		final double radius = diameter / 2;
		return dx * dx + dy * dy <= radius * radius;
	}
}

package com.compassonly;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CompassOnlyConfig.GROUP)
public interface CompassOnlyConfig extends Config
{
	String GROUP = "compassonly";
	String HIDE_FRAME = "hideFrame";
	int MIN_SIZE = 10;
	int MAX_SIZE = 1000;

	@Range(min = MIN_SIZE, max = MAX_SIZE)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "compassSize",
		name = "Compass size",
		description = "Size of the compass. 100% fills the minimap's space. Above 100% it grows past the minimap and is drawn on top of the interface.",
		position = 0
	)
	default int compassSize()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "smoothScaling",
		name = "Smooth scaling",
		description = "Smooth the enlarged compass instead of keeping hard pixel edges",
		position = 1
	)
	default boolean smoothScaling()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lookOptions",
		name = "Click to look north",
		description = "Left-click the compass to face north, right-click it for south, east and west",
		position = 2
	)
	default boolean lookOptions()
	{
		return true;
	}

	@ConfigItem(
		keyName = HIDE_FRAME,
		name = "Hide minimap frame",
		description = "Also hide the stone frame around the minimap, leaving the orbs. Resizable layouts only.",
		position = 3
	)
	default boolean hideFrame()
	{
		return false;
	}
}

package com.compassonly;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.TexturePaint;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Paints the enlarged compass where the minimap used to be.
 *
 * Two of these are registered. The layered one is painted part-way through the game's own
 * interface drawing, at the point the minimap would have been painted, so the minimap frame
 * and the orbs end up on top of it exactly as they did with the minimap. The other is a
 * safety net that paints over the finished interface on any frame the layered one missed.
 */
class CompassOnlyOverlay extends Overlay
{
	private static final double JAU14_TO_RADIANS = Math.PI / 8192.0;

	// The game rotates the compass sprite about this pixel
	private static final double SPRITE_CENTER = 25.5;

	private static final Color OUTLINE_COLOR = new Color(20, 16, 10, 230);
	private static final double OUTLINE_WIDTH = 2;

	private static final double MIN_HOLE_COVERAGE = 0.4;
	private static final double MAX_HOLE_COVERAGE = 0.99;
	private static final int MASK_SIZE_TOLERANCE = 2;

	private final Client client;
	private final CompassOnlyPlugin compassPlugin;
	private final CompassOnlyConfig config;
	private final SpriteManager spriteManager;
	private final boolean layered;

	// Mask sprite id -> the hole it describes, or null if the sprite was not usable
	private final Map<Integer, Hole> holes = new HashMap<>();

	CompassOnlyOverlay(Client client, CompassOnlyPlugin plugin, CompassOnlyConfig config, SpriteManager spriteManager, boolean layered)
	{
		super(plugin);
		this.client = client;
		this.compassPlugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;
		this.layered = layered;

		setPosition(OverlayPosition.DYNAMIC);

		if (layered)
		{
			setLayer(OverlayLayer.MANUAL);
			// Resizable: the last piece drawn before the compass, the minimap and then the frame
			drawAfterLayer(InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_5);
			drawAfterLayer(InterfaceID.ToplevelPreEoc.MAP_NOCLICK_5);
			// Fixed: nothing usable comes before the frame, so go directly after it and before the orbs
			drawAfterLayer(InterfaceID.Toplevel.COMPASSCLICK);
		}
		else
		{
			setLayer(OverlayLayer.ABOVE_WIDGETS);
		}
	}

	@Override
	public String getName()
	{
		return layered ? "CompassOnlyOverlayLayered" : "CompassOnlyOverlayFallback";
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final CompassGeometry geo = compassPlugin.getGeometry();
		if (geo == null || compassPlugin.isCompassDrawn())
		{
			return null;
		}

		// A compass bigger than the minimap's space would be cut off by the frame and orbs
		// drawn after it, so leave it to the pass that draws over the finished interface
		if (layered && geo.isOversized())
		{
			return null;
		}

		final BufferedImage sprite = spriteManager.getSprite(SpriteID.COMPASS, 0);
		if (sprite == null)
		{
			return null;
		}

		final Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			draw(g, geo, sprite);
		}
		finally
		{
			g.dispose();
		}

		compassPlugin.setCompassDrawn(true);
		return null;
	}

	private void draw(Graphics2D g, CompassGeometry geo, BufferedImage sprite)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, config.smoothScaling()
			? RenderingHints.VALUE_INTERPOLATION_BILINEAR
			: RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

		if (!client.isResized())
		{
			prepareFixedMode(g, geo);
		}

		final double sourceRadius = geo.getSourceDiameter() / 2;
		final double scale = geo.getDiameter() / geo.getSourceDiameter();
		final double yaw = (client.getCameraYawTarget() & 0x3fff) * JAU14_TO_RADIANS;

		// From here on drawing is in compass sprite pixels, centred on the compass
		g.translate(geo.getCenterX(), geo.getCenterY());
		g.rotate(yaw);
		g.scale(scale, scale);

		final Ellipse2D dial = new Ellipse2D.Double(-sourceRadius, -sourceRadius, sourceRadius * 2, sourceRadius * 2);

		// The game treats the sprite as fully opaque, with its transparent pixels as black
		g.setColor(Color.BLACK);
		g.fill(dial);
		g.setPaint(new TexturePaint(sprite,
			new Rectangle2D.Double(-SPRITE_CENTER, -SPRITE_CENTER, sprite.getWidth(), sprite.getHeight())));
		g.fill(dial);

		// Keep the outline inside the dial so it never spills onto the minimap frame
		final double outlineWidth = OUTLINE_WIDTH / scale;
		final double outlineRadius = sourceRadius - outlineWidth / 2;
		g.setColor(OUTLINE_COLOR);
		g.setStroke(new BasicStroke((float) outlineWidth));
		g.draw(new Ellipse2D.Double(-outlineRadius, -outlineRadius, outlineRadius * 2, outlineRadius * 2));
	}

	/**
	 * In fixed mode the minimap and compass sit in holes cut out of the frame artwork, with
	 * nothing behind them. Once they are hidden those holes keep showing whatever was drawn
	 * there last, so paint them black, then confine the compass to the minimap's hole because
	 * here it is drawn on top of the frame rather than underneath it.
	 */
	private void prepareFixedMode(Graphics2D g, CompassGeometry geo)
	{
		final Rectangle minimapBounds = geo.getMinimapBounds();
		final Hole minimapHole = hole(geo.getMinimapMaskSprite(), minimapBounds);
		blackOut(g, minimapBounds, minimapHole);

		final Rectangle compassBounds = geo.getCompassBounds();
		if (compassBounds != null)
		{
			blackOut(g, compassBounds, hole(geo.getCompassMaskSprite(), compassBounds));
		}

		if (minimapHole != null && !geo.isOversized())
		{
			g.translate(minimapBounds.x, minimapBounds.y);
			g.clip(minimapHole.shape);
			g.translate(-minimapBounds.x, -minimapBounds.y);
		}
	}

	private static void blackOut(Graphics2D g, Rectangle bounds, Hole hole)
	{
		if (hole != null)
		{
			g.drawImage(hole.image, bounds.x, bounds.y, null);
		}
		else
		{
			g.setColor(Color.BLACK);
			g.fill(new Ellipse2D.Double(bounds.x, bounds.y, bounds.width, bounds.height));
		}
	}

	/**
	 * The minimap and compass widgets each carry a mask sprite whose shape is exactly the
	 * hole they show through.
	 */
	private Hole hole(int maskSpriteId, Rectangle bounds)
	{
		if (maskSpriteId < 0)
		{
			return null;
		}
		if (holes.containsKey(maskSpriteId))
		{
			return holes.get(maskSpriteId);
		}

		final BufferedImage mask = spriteManager.getSprite(maskSpriteId, 0);
		if (mask == null)
		{
			// Not loaded yet, try again next frame
			return null;
		}

		final Hole hole = Hole.fromMask(mask, bounds);
		holes.put(maskSpriteId, hole);
		return hole;
	}

	private static final class Hole
	{
		/** The hole filled solid black on a transparent background. */
		private final BufferedImage image;
		/** The outline of the hole, relative to the top left of the mask. */
		private final Area shape;

		private Hole(BufferedImage image, Area shape)
		{
			this.image = image;
			this.shape = shape;
		}

		private static Hole fromMask(BufferedImage mask, Rectangle bounds)
		{
			final int width = mask.getWidth();
			final int height = mask.getHeight();
			if (Math.abs(width - bounds.width) > MASK_SIZE_TOLERANCE || Math.abs(height - bounds.height) > MASK_SIZE_TOLERANCE)
			{
				return null;
			}

			// The corner of the sprite is always outside the hole, whichever way round the
			// mask happens to be stored. Each row of the hole runs from its first inside
			// pixel to its last.
			final boolean outsideIsOpaque = isOpaque(mask.getRGB(0, 0));
			final BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
			final Area shape = new Area();
			int covered = 0;

			for (int y = 0; y < height; y++)
			{
				int first = -1;
				int last = -1;
				for (int x = 0; x < width; x++)
				{
					if (isOpaque(mask.getRGB(x, y)) != outsideIsOpaque)
					{
						if (first == -1)
						{
							first = x;
						}
						last = x;
					}
				}

				if (first == -1)
				{
					continue;
				}

				final int length = last - first + 1;
				for (int x = first; x <= last; x++)
				{
					image.setRGB(x, y, 0xFF000000);
				}
				shape.add(new Area(new Rectangle(first, y, length, 1)));
				covered += length;
			}

			final double coverage = (double) covered / (width * height);
			if (coverage < MIN_HOLE_COVERAGE || coverage > MAX_HOLE_COVERAGE)
			{
				return null;
			}

			return new Hole(image, shape);
		}

		private static boolean isOpaque(int argb)
		{
			return (argb >>> 24) != 0;
		}
	}
}

package com.compassonly;

import com.google.inject.Provides;
import java.awt.Rectangle;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Compass Only",
	description = "Hides the minimap and shows an enlarged compass in its place",
	tags = {"minimap", "compass", "hide", "hud", "immersion"}
)
public class CompassOnlyPlugin extends Plugin
{
	// The game marks the widgets it paints the minimap and the compass into with these
	private static final int CONTENT_TYPE_MINIMAP = 1338;
	private static final int CONTENT_TYPE_COMPASS = 1339;

	// Fixed, resizable classic and resizable modern
	private static final int[] LAYOUTS = {
		InterfaceID.TOPLEVEL,
		InterfaceID.TOPLEVEL_OSRS_STRETCH,
		InterfaceID.TOPLEVEL_PRE_EOC
	};

	private static final int MAX_COMPONENTS = 400;
	private static final int MAX_DEPTH = 32;
	private static final double DEFAULT_SOURCE_DIAMETER = 33;
	private static final int MIN_SIZE_PERCENT = CompassOnlyConfig.MIN_SIZE;
	private static final int MAX_SIZE_PERCENT = CompassOnlyConfig.MAX_SIZE;

	// Camera yaw is measured in 1/16384ths of a turn, increasing anticlockwise from north
	private static final int YAW_NORTH = 0;
	private static final int YAW_WEST = 4096;
	private static final int YAW_SOUTH = 8192;
	private static final int YAW_EAST = 12288;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CompassOnlyConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpriteManager spriteManager;

	private CompassOnlyOverlay layeredOverlay;
	private CompassOnlyOverlay fallbackOverlay;

	// Everything below is only touched on the client thread
	private int partsLayout = -1;
	private MinimapParts parts = new MinimapParts();

	/**
	 * Where the compass belongs on the frame being drawn, or null if it should not be drawn.
	 */
	@Getter(AccessLevel.PACKAGE)
	private CompassGeometry geometry;

	/**
	 * Whether the compass has been painted on the frame being drawn. Outside of rendering
	 * this still holds the answer for the last frame.
	 */
	@Getter(AccessLevel.PACKAGE)
	@Setter(AccessLevel.PACKAGE)
	private boolean compassDrawn;

	@Provides
	CompassOnlyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CompassOnlyConfig.class);
	}

	@Override
	protected void startUp()
	{
		layeredOverlay = new CompassOnlyOverlay(client, this, config, spriteManager, true);
		fallbackOverlay = new CompassOnlyOverlay(client, this, config, spriteManager, false);
		overlayManager.add(layeredOverlay);
		overlayManager.add(fallbackOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(layeredOverlay);
		overlayManager.remove(fallbackOverlay);
		layeredOverlay = null;
		fallbackOverlay = null;
		clientThread.invoke(this::restoreWidgets);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CompassOnlyConfig.GROUP.equals(event.getGroup())
			&& CompassOnlyConfig.HIDE_FRAME.equals(event.getKey())
			&& !config.hideFrame())
		{
			clientThread.invoke(() ->
			{
				for (int layout : LAYOUTS)
				{
					show(findParts(layout).frame);
				}
			});
		}
	}

	/**
	 * The game's scripts un-hide interface pieces whenever they rebuild the layout, so the
	 * minimap is re-hidden right before every frame rather than once.
	 */
	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		compassDrawn = false;
		geometry = null;

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		locateParts();
		if (parts.minimap == null)
		{
			return;
		}

		hide(parts.minimap);
		hide(parts.compass);
		if (config.hideFrame())
		{
			hide(parts.frame);
		}

		geometry = computeGeometry();
	}

	/**
	 * Gives the enlarged compass the same click options as the game's own compass.
	 */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		final CompassGeometry geo = geometry;
		if (geo == null || !compassDrawn || !config.lookOptions()
			|| client.isMenuOpen() || client.isWidgetSelected())
		{
			return;
		}

		final Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !geo.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}

		// Leave the menu alone if the mouse is over something of its own, such as an
		// orb or a window that happens to sit on top of the compass
		final Menu menu = client.getMenu();
		final MenuEntry[] entries = menu.getMenuEntries();
		if (entries.length > 0)
		{
			final MenuAction top = entries[entries.length - 1].getType();
			if (top != MenuAction.CANCEL && top != MenuAction.WALK)
			{
				return;
			}
		}

		// Each entry is added above the previous one, and the topmost is the left-click action
		addLookOption(menu, "Look West", YAW_WEST);
		addLookOption(menu, "Look East", YAW_EAST);
		addLookOption(menu, "Look South", YAW_SOUTH);
		addLookOption(menu, "Look North", YAW_NORTH);
	}

	private void addLookOption(Menu menu, String option, int yaw)
	{
		menu.createMenuEntry(-1)
			.setOption(option)
			.setTarget("")
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> client.setCameraYawTarget(yaw));
	}

	private void locateParts()
	{
		final int layout = client.getTopLevelInterfaceId();
		if (layout == partsLayout && isCurrent(parts.minimap))
		{
			return;
		}

		partsLayout = layout;
		parts = findParts(layout);
	}

	/**
	 * Widgets are rebuilt when an interface reloads, which leaves old references pointing at nothing.
	 */
	private boolean isCurrent(Widget widget)
	{
		return widget != null && client.getWidget(widget.getId()) == widget;
	}

	/**
	 * Finds the minimap pieces by what they are rather than by component id, so a game
	 * update that renumbers the interface does not make the plugin hide the wrong thing.
	 */
	private MinimapParts findParts(int layout)
	{
		final MinimapParts found = new MinimapParts();
		if (layout < 0)
		{
			return found;
		}

		for (int child = 0; child < MAX_COMPONENTS; child++)
		{
			final Widget widget = client.getWidget(layout, child);
			if (widget == null)
			{
				continue;
			}

			final int contentType = widget.getContentType();
			if (contentType == CONTENT_TYPE_MINIMAP)
			{
				found.minimap = widget;
			}
			else if (contentType == CONTENT_TYPE_COMPASS)
			{
				found.compass = widget;
			}
			else if (widget.getSpriteId() == SpriteID.OSRS_STRETCH_MAPSURROUND)
			{
				found.frame = widget;
			}
		}

		if (found.frame != null
			&& (found.minimap == null || found.frame.getParentId() != found.minimap.getParentId()))
		{
			found.frame = null;
		}

		return found;
	}

	private CompassGeometry computeGeometry()
	{
		final Widget minimap = parts.minimap;

		// If the game's own setting or another plugin has hidden the whole minimap block,
		// orbs get rearranged into this space, so stay out of the way
		final Widget container = minimap.getParent();
		if (container == null || container.isHidden())
		{
			return null;
		}

		final Rectangle minimapBounds = canvasBounds(minimap);
		if (minimapBounds.isEmpty())
		{
			return null;
		}

		Rectangle compassBounds = null;
		int compassMask = -1;
		double sourceDiameter = DEFAULT_SOURCE_DIAMETER;
		if (parts.compass != null)
		{
			compassBounds = canvasBounds(parts.compass);
			compassMask = parts.compass.getSpriteId();
			if (!compassBounds.isEmpty())
			{
				sourceDiameter = Math.min(compassBounds.width, compassBounds.height);
			}
		}

		final int sizePercent = Math.max(MIN_SIZE_PERCENT, Math.min(MAX_SIZE_PERCENT, config.compassSize()));
		final boolean oversized = sizePercent > 100;
		double diameter = Math.min(minimapBounds.width, minimapBounds.height) * sizePercent / 100.0;
		double centerX = minimapBounds.getCenterX();
		double centerY = minimapBounds.getCenterY();

		if (oversized)
		{
			// Grow from the minimap's centre, but slide back inwards so none of it is
			// pushed off the edge of the game window
			final int canvasWidth = client.getCanvasWidth();
			final int canvasHeight = client.getCanvasHeight();
			diameter = Math.min(diameter, Math.min(canvasWidth, canvasHeight));
			final double radius = diameter / 2;
			centerX = clamp(centerX, radius, canvasWidth - radius);
			centerY = clamp(centerY, radius, canvasHeight - radius);
		}

		return new CompassGeometry(
			minimapBounds,
			minimap.getSpriteId(),
			compassBounds,
			compassMask,
			centerX,
			centerY,
			diameter,
			sourceDiameter,
			oversized);
	}

	private static double clamp(double value, double min, double max)
	{
		return max < min ? (min + max) / 2 : Math.max(min, Math.min(max, value));
	}

	/**
	 * A hidden widget's reported canvas location goes stale because the game only updates it
	 * while drawing, so add up the offset within each parent instead.
	 */
	private static Rectangle canvasBounds(Widget widget)
	{
		int x = 0;
		int y = 0;
		Widget current = widget;
		for (int depth = 0; current != null && depth < MAX_DEPTH; depth++)
		{
			x += current.getRelativeX();
			y += current.getRelativeY();
			current = current.getParent();
		}
		return new Rectangle(x, y, widget.getWidth(), widget.getHeight());
	}

	private void restoreWidgets()
	{
		// A layout that was used earlier stays loaded with its pieces still hidden, so
		// restore all of them and not only the one on screen
		for (int layout : LAYOUTS)
		{
			restore(findParts(layout));
		}
		restore(parts);

		parts = new MinimapParts();
		partsLayout = -1;
		geometry = null;
		compassDrawn = false;
	}

	private static void restore(MinimapParts target)
	{
		show(target.minimap);
		show(target.compass);
		show(target.frame);
	}

	private static void hide(Widget widget)
	{
		if (widget != null && !widget.isSelfHidden())
		{
			widget.setHidden(true);
		}
	}

	private static void show(Widget widget)
	{
		if (widget != null && widget.isSelfHidden())
		{
			widget.setHidden(false);
		}
	}

	private static final class MinimapParts
	{
		private Widget minimap;
		private Widget compass;
		private Widget frame;
	}
}

